  function collect(){ ["lobbyView","roomView","myNickname","roomTitleInput","totalRoundsSelect","turnLimitSelect","roomList","rankPreview","roomStateText","roomTitle","turnBadge","messageBar","lobbyControls","readyBtn","watchBtn","joinAsPlayerBtn","startBtn","betweenControls","nextRoundBtn","resetGameBtn","playersArea","centerPile","handArea","selectedSummary","playControls","playBtn","passBtn","scoreList","chatList","chatInput","sendChatBtn","toggleSpectatorChatBtn","homeBtn","leaveRoomBtn","createRoomBtn","refreshRoomsBtn","toast"].forEach(id => E[id] = $(id)); }
