  function roleByIndex(i,n){ const map={2:["사바나","노비"],3:["사바나","농민","노비"],4:["사바나","세자","농민","노비"],5:["사바나","세자","사또","농민","노비"],6:["사바나","세자","암행어사","사또","농민","노비"],7:["사바나","세자","관찰사","암행어사","사또","농민","노비"],8:["사바나","세자","영의정","관찰사","암행어사","사또","농민","노비"]}; return (map[n]||[])[i]||`${i+1}등`; }
  function shuffle(a){ a=a.slice(); for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]];} return a; }
  function maxRank(n){ return n<=3?8:n<=5?10:12; }
  function sortHand(h=[]){ return h.slice().sort((a,b)=>a.rank-b.rank||String(a.id).localeCompare(String(b.id))); }
  function makeDeck(n){ const deck=[]; RANKS.filter(r=>r.rank<=maxRank(n)).forEach(r=>{ for(let i=1;i<=r.count;i++) deck.push({id:`r${r.rank}-${i}-${Math.random().toString(36).slice(2,8)}`,rank:r.rank,name:r.name}); }); for(let i=1;i<=2;i++) deck.push({id:`j-${i}-${Math.random().toString(36).slice(2,8)}`,rank:13,name:"홍길동",joker:true}); return shuffle(deck); }
  function groupHand(h=[]){ const m=new Map(); sortHand(h).forEach(c=>{ if(!m.has(c.rank))m.set(c.rank,[]); m.get(c.rank).push(c);}); return [...m.entries()].map(([rank,items])=>({rank,items})); }
  function selectedCards(){ const ids=new Set(); S.selected.forEach(items=>items.forEach(c=>ids.add(c.id))); return S.hand.filter(c=>ids.has(c.id)); }
  function normalize(cards){ if(!cards.length) return {ok:false,reason:"카드를 선택하세요."}; const ns=cards.filter(c=>!c.joker), ranks=[...new Set(ns.map(c=>c.rank))]; if(ranks.length>1)return{ok:false,reason:"같은 계급만 함께 낼 수 있습니다."}; if(!ns.length)return{ok:true,effectiveRank:13,effectiveName:"홍길동",count:cards.length,cards}; return{ok:true,effectiveRank:ranks[0],effectiveName:rankInfo(ranks[0]).name,count:cards.length,cards}; }
  function canPlay(cards,room=S.room){ const c=normalize(cards), cur=room?.currentSet; if(!c.ok||!cur)return c; if(c.count!==cur.count)return{ok:false,reason:`이번 판은 ${cur.count}장씩 내야 합니다.`}; if(c.effectiveRank>=cur.effectiveRank)return{ok:false,reason:"더 높은 계급만 낼 수 있습니다."}; return c; }
  function nextAfter(uid){ const a=activePlayers(); if(!a.length)return""; const i=Math.max(0,a.findIndex(p=>p.uid===uid)); return a[(i+1)%a.length]?.uid||a[0]?.uid||""; }
  function myTribute(){ return (S.room?.tribute?.pairs||[]).find(p=>p.toUid===S.user&&!p.returned)||null; }
  function bestTribute(h,c){ return sortHand(h).filter(x=>!x.joker&&x.rank!==13).slice(0,c); }
  function dot(k){ return new firebase.firestore.FieldPath(...k.split(".")); }
