  function sPath(uid,field){ return `spectators.${uid}.${field}`; }
  async function addSystem(text){ if(!S.roomId)return; await appendChat({type:"system",text}); }
  async function appendChat(msg){ const chat=(S.room?.chatPreview||[]).slice(-CHAT_LIMIT+1); chat.push({...msg, uid:msg.uid||"system", nickname:msg.nickname||"", text:msg.text||"", createdAt:Date.now()}); await roomRef().set({chatPreview:chat,updatedAt:FV.serverTimestamp()},{merge:true}); }

  function renderRanks(){ E.rankPreview.innerHTML=RANKS.map(r=>`<span class="rank-chip">${r.code}. ${esc(r.name)}</span>`).join(""); }
  async function loadRooms(){ const snap=await roomCol().orderBy("updatedAt","desc").limit(30).get(); const docs=snap.docs.filter(d=>!d.data().closed&&d.data().status!=="closed"); E.roomList.innerHTML=docs.length?docs.map(d=>{const r=d.data(), st=({waiting:"대기 중",playing:"진행 중",betweenRounds:"라운드 종료",tributeReturn:"상납 반환",finished:"게임 종료"})[r.status]||r.status;return`<div class="room-item"><div><strong>${esc(r.title||"사바나 달무티")}</strong><div class="room-meta">${st} · 플레이어 ${r.playerCount||0}/${MAX_PLAYERS} · 관전자 ${r.spectatorCount||0} · ${r.totalRounds?`${r.totalRounds}판`:"무제한"}</div></div><button class="btn primary" type="button" onclick="Dalmuti.joinRoom('${d.id}')">입장</button></div>`}).join(""):`<div class="muted">생성된 방이 없습니다.</div>`; }
  function positions(){ const ps=allPlayers(), mi=Math.max(0,ps.findIndex(p=>p.uid===S.user)), rot=mi>=0?ps.slice(mi).concat(ps.slice(0,mi)):ps, mine=rot[0], o=rot.slice(1); let left=[],top=[],right=[]; if(o.length===1)top=o; else if(o.length===2){left=[o[0]];right=[o[1]];} else if(o.length===3){left=[o[0]];top=[o[1]];right=[o[2]];} else if(o.length===4){left=[o[0]];top=[o[1],o[2]];right=[o[3]];} else if(o.length===5){left=[o[0],o[1]];top=[o[2],o[3]];right=[o[4]];} else if(o.length===6){left=[o[0],o[1]];top=[o[2],o[3]];right=[o[4],o[5]];} else {left=[o[0],o[1]];top=[o[2],o[3],o[4]];right=[o[5],o[6]];} return [...(mine?[{p:mine,cls:"seat-bottom"}]:[]),...left.map((p,i)=>({p,cls:`seat-left-${left.length===1?0:i+1}`})),...top.map((p,i)=>({p,cls:`seat-top-${top.length===1?0:i}`})),...right.map((p,i)=>({p,cls:`seat-right-${right.length===1?0:i+1}`}))]; }
  function renderPlayers(){ E.playersArea.innerHTML=positions().map(({p,cls})=>{const sub=S.room?.currentSet?.uid===p.uid, state=p.finished?`${p.finishedRank||""}등`:p.passed?"패스":`${p.cardCount||0}장`; let badge=p.isAI?`<div class="badge ai">AI</div>`:""; if(sub)badge+=`<div class="badge submit">제출</div>`; else if(p.passed)badge+=`<div class="badge pass">패스</div>`; else if(S.room?.currentTurnUid===p.uid)badge+=`<div class="badge turn">차례</div>`; const kick=isHost()&&p.uid!==S.user?`<button class="kick-btn" type="button" onclick="Dalmuti.kick('${p.uid}')">강퇴</button>`:""; return`<div class="player-box ${cls} ${p.uid===S.user?"me":""} ${S.room?.currentTurnUid===p.uid?"turn":""} ${p.passed?"passed":""} ${p.finished?"finished":""} ${sub?"submitted":""} ${p.forfeited?"forfeited":""}">${kick}<div class="player-role">${esc(p.role||"참가자")}</div><div class="player-name">${esc(p.nickname)}</div><div class="player-meta">${state}${p.isReady?" · 준비":""}</div>${badge}</div>`}).join(""); }
  function renderPile(){ if(S.room?.status==="tributeReturn"){ const pairs=S.room.tribute?.pairs||[]; E.centerPile.innerHTML=`<div class="pile-title">상납 반환</div><div class="muted">상납 받은 사람이 돌려줄 카드를 선택합니다.</div><div class="muted">${pairs.map(p=>`${esc(p.fromNickname)} → ${esc(p.toNickname)} ${p.count}장 ${p.returned?"완료":"대기"}`).join("<br>")}</div>`; return;} const prev=S.room?.previousSet, cur=S.room?.currentSet; if(!prev&&!cur){E.centerPile.innerHTML=`<div class="pile-board"><div class="pile-empty">새 판</div></div>`;return;} const prevCard=prev?.cards?.[0]?`<img src="${cardImg(prev.cards[0].rank)}" alt="직전 카드">`:`<span class="muted">없음</span>`; const curCards=cur?(cur.cards||[]).map(c=>`<img src="${cardImg(c.rank)}" alt="${esc(c.name)}">`).join(""):`<span class="muted">제출 대기</span>`; E.centerPile.innerHTML=`<div class="pile-board"><div class="prev-pile"><div class="prev-pile-title">직전 카드</div>${prevCard}</div><div class="cur-pile"><div class="cur-pile-title">${cur?`현재 ${rankInfo(cur.effectiveRank).name} ${cur.count}장`:"현재 없음"}</div><div class="cur-cards">${curCards}</div></div></div>`; }
  function selectable(g){ if(S.room?.status==="tributeReturn")return!!myTribute(); if(S.room?.status!=="playing"||S.room.currentTurnUid!==S.user||!S.room.currentSet)return true; if(g.rank===13)return false; const need=S.room.currentSet.count, jc=S.hand.filter(c=>c.joker).length; return g.items.length+jc>=need && g.rank<S.room.currentSet.effectiveRank; }
